blocks.code:
type SortOrder = 'recommended' | 'price-asc' | 'rating-desc';

interface SearchQuery {
  city: string;
  checkIn: string;
  checkOut: string;
  adults: number;
  children: number;
  filters: Record<string, string[]>;
  sort: SortOrder;
  page: number;
}

interface PriceQuote {
  amount: number;
  currency: string;
  quotedAt: string;
}

interface ResultCard {
  hotelId: string;
  name: string;
  rating: number;
  price: PriceQuote;
}

interface FacetCount {
  filter: string;
  value: string;
  count: number;
}

type ResultsPhase = 'idle' | 'loading' | 'ready' | 'error';

interface ResultsState {
  queryId: string;
  phase: ResultsPhase;
  cards: ResultCard[];
  facets: FacetCount[];
  total: number;
  nextPage: number | null;
  errorCode: string | null;
}

interface UnitManifest {
  unit: 'inputs' | 'filters' | 'results';
  buildId: string;
  entryUrl: string;
  contractVersion: number;
}
